def write_cli_bin(dirpath: Path, scripts: dict) -> Path:
    dirpath.mkdir(parents=True, exist_ok=True)
    for name, body in scripts.items():
        script = dirpath / name
        script.write_text(f"#!/bin/sh\n{body}\n", encoding="utf-8")
        script.chmod(0o755)
    return dirpath


write_cli_bin(FAKE_BIN, FAKE_CLI_SCRIPTS)


def isolated_env(extra: dict | None = None) -> dict:
    env = os.environ.copy()
    for key in list(env):
        if key.startswith("AGENTS_OVERLAY_"):
            env.pop(key)
    env.pop("CLAUDE_CODE_DISABLE_CLAUDE_MDS", None)
    env["GIT_CONFIG_GLOBAL"] = "/dev/null"
    env["GIT_CONFIG_SYSTEM"] = "/dev/null"
    env["CODEX_HOME"] = str(EMPTY_CODEX_HOME)
    env["HOME"] = str(EMPTY_HOME)
    env["PATH"] = f"{FAKE_BIN}:{env['PATH']}"
    if extra:
        env.update(extra)
    return env


def run_core(
    args: list[str],
    cwd: Path,
    stdin: str = "",
    extra_env: dict | None = None,
) -> subprocess.CompletedProcess:
    return subprocess.run(
        [sys.executable, str(CORE), *args],
        cwd=str(cwd),
        input=stdin,
        capture_output=True,
        text=True,
        env=isolated_env(extra_env),
        timeout=60,
    )


def run_git(cwd: Path, *args: str) -> None:
    subprocess.run(
        ["git", "-c", "user.email=t@example.test", "-c", "user.name=t", *args],
        cwd=str(cwd),
        check=True,
        capture_output=True,
        env=isolated_env(),
    )


def make_repo(base: Path, name: str = "repo", local: bool = True) -> Path:
    repo = base / name
    repo.mkdir()
    run_git(repo, "init", "-q")
    (repo / "AGENTS.md").write_text("# shared\nshared rule X\n", encoding="utf-8")
    if local:
        (repo / "AGENTS.local.md").write_text("# local\nlocal rule Y\n", encoding="utf-8")
    run_git(repo, "add", "AGENTS.md")
    run_git(repo, "commit", "-qm", "init")
    return repo


def hook_stdin(cwd: Path, **fields) -> str:
    return json.dumps({"cwd": str(cwd), **fields})


def make_ignored_shared_repo(base: Path) -> Path:
    repo = base / "repo"
    repo.mkdir()
    run_git(repo, "init", "-q")
    (repo / "README.md").write_text("readme\n", encoding="utf-8")
    run_git(repo, "add", "README.md")
    run_git(repo, "commit", "-qm", "init")
    (repo / "AGENTS.md").write_text("# shared\nshared rule X\n", encoding="utf-8")
    (repo / "AGENTS.local.md").write_text("# local\nlocal rule Y\n", encoding="utf-8")
    return repo


def hook_context(proc: subprocess.CompletedProcess) -> str:
    payload = json.loads(proc.stdout)
    return payload["hookSpecificOutput"]["additionalContext"]


CLAUDE_SESSION = ["json", "SessionStart", "CLAUDE.md", "CLAUDE.local.md", ".", "claude-session"]
CLAUDE_SUBAGENT = ["json", "SubagentStart", "CLAUDE.md", "CLAUDE.local.md", ".", "claude-subagent"]
CODEX_SESSION = ["json", "SessionStart", "AGENTS.md", "-", ".", "codex-session"]
CODEX_SUBAGENT = ["json", "SubagentStart", "AGENTS.md", "-", ".", "codex-subagent"]


class OverlayTestCase(unittest.TestCase):
    def setUp(self) -> None:
        self._tmp = tempfile.TemporaryDirectory(prefix="agents-overlay-case-")
        self.base = Path(self._tmp.name).resolve()
        self.addCleanup(self._tmp.cleanup)

    def setup_repo(self, repo: Path) -> subprocess.CompletedProcess:
        proc = run_core(["setup"], repo)
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        return proc

    def add_worktree(self, repo: Path, name: str = "wt") -> Path:
        target = self.base / name
        run_git(repo, "worktree", "add", "-q", str(target))
        return target.resolve()


class SetupTests(OverlayTestCase):
    def test_creates_bridges_ignores_and_passes_verify(self) -> None:
        repo = make_repo(self.base)
        proc = self.setup_repo(repo)
        self.assertEqual((repo / "CLAUDE.md").read_text(encoding="utf-8"), "@AGENTS.md\n")
        self.assertEqual(
            (repo / "CLAUDE.local.md").read_text(encoding="utf-8"), "@AGENTS.local.md\n"
        )
        gitignore = (repo / ".gitignore").read_text(encoding="utf-8")
        for pattern in ("AGENTS.local.md", "CLAUDE.local.md", ".kiro/steering/agents-local-overlay.md"):
            self.assertIn(pattern, gitignore)
        self.assertIn("verify: OK", proc.stdout)

    def test_requires_a_rule_source(self) -> None:
        repo = self.base / "empty"
        repo.mkdir()
        run_git(repo, "init", "-q")
        proc = run_core(["setup"], repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("create AGENTS.md and/or AGENTS.local.md", proc.stderr)

    def test_normalizes_crlf_bridge(self) -> None:
        repo = make_repo(self.base)
        (repo / "CLAUDE.md").write_bytes(b"@AGENTS.md\r\n")
        self.setup_repo(repo)
        self.assertEqual((repo / "CLAUDE.md").read_bytes(), b"@AGENTS.md\n")

    def test_rejects_bridge_with_extra_content(self) -> None:
        repo = make_repo(self.base)
        (repo / "CLAUDE.md").write_text("@AGENTS.md\nmore prose\n", encoding="utf-8")
        proc = run_core(["setup"], repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("content beyond the @AGENTS.md import", proc.stderr)
        self.assertEqual(
            (repo / "CLAUDE.md").read_text(encoding="utf-8"), "@AGENTS.md\nmore prose\n"
        )

    def test_materializes_generated_copy_in_linked_worktree(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        run_git(repo, "add", "CLAUDE.md", ".gitignore")
        run_git(repo, "commit", "-qm", "bridge")
        worktree = self.add_worktree(repo)
        self.setup_repo(worktree)
        copy = (worktree / "CLAUDE.local.md").read_text(encoding="utf-8")
        self.assertTrue(copy.startswith(GENERATED_OWNER + "\n"))
        self.assertIn("local rule Y", copy)

    def test_removes_orphan_generated_copy(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        run_git(repo, "add", "CLAUDE.md", ".gitignore")
        run_git(repo, "commit", "-qm", "bridge")
        worktree = self.add_worktree(repo)
        self.setup_repo(worktree)
        (repo / "AGENTS.local.md").unlink()
        proc = self.setup_repo(repo)
        self.assertIn("removed orphan generated copy", proc.stdout)
        self.assertFalse((worktree / "CLAUDE.local.md").exists())

    def test_second_run_changes_nothing(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        proc = self.setup_repo(repo)
        self.assertNotIn("changed:", proc.stdout)


class VerifyTests(OverlayTestCase):
    def test_fails_on_stale_generated_copy(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        run_git(repo, "add", "CLAUDE.md", ".gitignore")
        run_git(repo, "commit", "-qm", "bridge")
        worktree = self.add_worktree(repo)
        self.setup_repo(worktree)
        (repo / "AGENTS.local.md").write_text("changed local\n", encoding="utf-8")
        proc = run_core(["verify"], worktree)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("is stale", proc.stdout)

    def test_fails_on_tracked_local_bridge(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        run_git(repo, "add", "-f", "CLAUDE.local.md")
        run_git(repo, "commit", "-qm", "oops")
        proc = run_core(["verify"], repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("CLAUDE.local.md is tracked", proc.stdout)

    def test_fails_on_codex_override_file(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        (repo / "AGENTS.override.md").write_text("override\n", encoding="utf-8")
        proc = run_core(["verify"], repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("AGENTS.override.md replaces AGENTS.md", proc.stdout)

    def test_fails_on_nested_worktrees(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        run_git(repo, "worktree", "add", "-q", str(repo / "nested"))
        proc = run_core(["verify"], repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("worktrees must not nest", proc.stdout)

    @staticmethod
    def _write_claude_settings(repo: Path, data: dict, local: bool = False) -> None:
        d = repo / ".claude"
        d.mkdir(exist_ok=True)
        name = "settings.local.json" if local else "settings.json"
        (d / name).write_text(json.dumps(data), encoding="utf-8")

    def test_fails_on_disable_all_hooks(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        self._write_claude_settings(repo, {"disableAllHooks": True})
        proc = run_core(["verify"], repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("disableAllHooks is true", proc.stdout)

    def test_fails_when_claude_md_excludes_shared_bridge(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        self._write_claude_settings(repo, {"claudeMdExcludes": ["**/CLAUDE.md"]})
        proc = run_core(["verify"], repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("claudeMdExcludes matches", proc.stdout)
        self.assertIn("CLAUDE.md", proc.stdout)

    def test_fails_when_claude_md_excludes_local_bridge(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        self._write_claude_settings(
            repo, {"claudeMdExcludes": ["**/CLAUDE.local.md"]}, local=True
        )
        proc = run_core(["verify"], repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("claudeMdExcludes matches", proc.stdout)
        self.assertIn("CLAUDE.local.md", proc.stdout)

    def test_ok_when_claude_md_excludes_unrelated_path(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        self._write_claude_settings(
            repo, {"claudeMdExcludes": ["**/somewhere-else/CLAUDE.md"]}
        )
        proc = run_core(["verify"], repo)
        self.assertEqual(proc.returncode, 0, proc.stdout)

    def test_ignores_claude_settings_in_non_overlay_repo(self) -> None:
        # A plain repo with no shared/local source has no overlay Claude channel,
        # so its project-level disableAllHooks must not produce a finding.
        repo = self.base / "plain"
        repo.mkdir()
        run_git(repo, "init", "-q")
        self._write_claude_settings(repo, {"disableAllHooks": True})
        proc = run_core(["verify"], repo)
        self.assertNotIn("disableAllHooks", proc.stdout)

    def _user_home_with_claude_settings(self, data: dict) -> dict:
        home = self.base / "home"
        (home / ".claude").mkdir(parents=True)
        (home / ".claude" / "settings.json").write_text(json.dumps(data), encoding="utf-8")
        return {"HOME": str(home)}

    def test_fails_on_disable_all_hooks_in_user_settings(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        env = self._user_home_with_claude_settings({"disableAllHooks": True})
        proc = run_core(["verify"], repo, extra_env=env)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("disableAllHooks is true", proc.stdout)
        self.assertIn(str(self.base / "home"), proc.stdout)

    def test_local_settings_override_user_disable_all_hooks(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        env = self._user_home_with_claude_settings({"disableAllHooks": True})
        self._write_claude_settings(repo, {"disableAllHooks": False}, local=True)
        proc = run_core(["verify"], repo, extra_env=env)
        self.assertEqual(proc.returncode, 0, proc.stdout)

    def test_claude_md_excludes_merge_across_layers(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        env = self._user_home_with_claude_settings(
            {"claudeMdExcludes": ["**/CLAUDE.md"]}
        )
        self._write_claude_settings(
            repo, {"claudeMdExcludes": ["**/CLAUDE.local.md"]}, local=True
        )
        proc = run_core(["verify"], repo, extra_env=env)
        self.assertEqual(proc.returncode, 1)
        self.assertEqual(proc.stdout.count("claudeMdExcludes matches"), 2)
        self.assertIn("/CLAUDE.md;", proc.stdout)
        self.assertIn("/CLAUDE.local.md;", proc.stdout)

    def test_reads_symlinked_claude_settings(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        dotfiles = self.base / "dotfiles"
        dotfiles.mkdir()
        (dotfiles / "settings.json").write_text(
            json.dumps({"disableAllHooks": True}), encoding="utf-8"
        )
        (repo / ".claude").mkdir()
        (repo / ".claude" / "settings.json").symlink_to(dotfiles / "settings.json")
        proc = run_core(["verify"], repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("disableAllHooks is true", proc.stdout)
        self.assertNotIn("could not read", proc.stdout)

    def test_claude_md_excludes_absolute_and_globstar_patterns(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        parent = str(repo.resolve().parent)
        cases = {
            f"{repo.resolve()}/CLAUDE.md": 1,
            f"{parent}/**": 1,
            f"{parent}/**/CLAUDE.md": 1,
            f"{parent}/*/CLAUDE.m?": 1,
            f"{parent}/**CLAUDE.md": 0,
            f"{parent}/*/*/CLAUDE.md": 0,
        }
        for pattern, expected in cases.items():
            self._write_claude_settings(repo, {"claudeMdExcludes": [pattern]})
            proc = run_core(["verify"], repo)
            self.assertEqual(proc.returncode, expected, f"{pattern}: {proc.stdout}")

    def test_warns_on_unevaluable_claude_md_excludes_pattern(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        self._write_claude_settings(
            repo, {"claudeMdExcludes": ["**/CLAUDE.{md,local.md}"]}
        )
        proc = run_core(["verify"], repo)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        self.assertIn("WARN: claudeMdExcludes pattern(s)", proc.stdout)
        self.assertIn("does not evaluate", proc.stdout)

