class KiroLauncherTests(OverlayTestCase):
    def run_launcher(self, repo: Path, extra_env: dict | None = None) -> subprocess.CompletedProcess:
        launcher_bin = write_cli_bin(
            self.base / "launcher-bin", {**FAKE_CLI_SCRIPTS, "kiro-cli": (
                'if [ "$1" = "settings" ] && [ "$2" = "list" ]; then\n'
                '  printf \'%s\\n\' \'{"chat.disableInheritingDefaultResources": false}\'\n'
                "  exit 0\nfi\necho KIRO-RUN \"$@\""
            )},
        )
        env = {"PATH": f"{launcher_bin}:{os.environ['PATH']}"}
        if extra_env:
            env.update(extra_env)
        return subprocess.run(
            [sys.executable, str(KIRO)],
            cwd=str(repo),
            capture_output=True,
            text=True,
            env=isolated_env(env),
            timeout=60,
        )

    def test_writes_steering_and_execs_kiro(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        proc = self.run_launcher(repo)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertIn("KIRO-RUN --v3", proc.stdout)
        steering = repo / ".kiro/steering/agents-local-overlay.md"
        text = steering.read_text(encoding="utf-8")
        self.assertTrue(text.startswith(KIRO_OWNER + "\n"))
        self.assertIn("local rule Y", text)
        self.assertNotIn("shared rule X", text)

    def test_removes_steering_when_local_source_missing(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        self.run_launcher(repo)
        (repo / "AGENTS.local.md").unlink()
        proc = self.run_launcher(repo)
        self.assertEqual(proc.returncode, 0, proc.stderr)
        self.assertFalse((repo / ".kiro/steering/agents-local-overlay.md").exists())

    def test_aborts_on_tracked_steering(self) -> None:
        repo = make_repo(self.base)
        self.setup_repo(repo)
        steering = repo / ".kiro/steering/agents-local-overlay.md"
        steering.parent.mkdir(parents=True, exist_ok=True)
        steering.write_text(KIRO_OWNER + "\n\nbody\n", encoding="utf-8")
        run_git(repo, "add", "-f", str(steering))
        proc = self.run_launcher(repo)
        self.assertEqual(proc.returncode, 1)
        self.assertIn("tracked", proc.stderr)


