class BareRepoTests(OverlayTestCase):
    def test_bare_primary_uses_metadata_dir_local_source(self) -> None:
        bare = self.base / "bare.git"
        subprocess.run(
            ["git", "init", "-q", "--bare", str(bare)],
            check=True,
            capture_output=True,
            env=isolated_env(),
        )
        seed = make_repo(self.base, name="seed")
        run_git(seed, "push", "-q", str(bare), "HEAD:main")
        checkout = self.base / "co"
        subprocess.run(
            ["git", "-C", str(bare), "worktree", "add", "-q", str(checkout), "main"],
            check=True,
            capture_output=True,
            env=isolated_env(),
        )
        (bare / "AGENTS.local.md").write_text("bare local B\n", encoding="utf-8")
        proc = run_core(CODEX_SESSION, checkout, stdin=hook_stdin(checkout))
        self.assertIn("bare local B", hook_context(proc))
        setup = run_core(["setup"], checkout)
        self.assertEqual(setup.returncode, 0, setup.stdout + setup.stderr)
        copy = checkout / "CLAUDE.local.md"
        self.assertTrue(copy.exists())
        text = copy.read_text(encoding="utf-8")
        self.assertTrue(text.startswith(GENERATED_OWNER + "\n"))
        self.assertIn("bare local B", text)


